import { remoteAgent } from 'genkit/beta/client';

/** URL of the deployed `testAgent` function in the emulator. */
export const FUNCTION_URL =
  'http://127.0.0.1:5001/demo-test/us-central1/testAgent';

const SIGN_UP_URL =
  'http://127.0.0.1:9099/identitytoolkit.googleapis.com/v1/accounts:signUp?key=fake-api-key';

let counter = 0;

/**
 * Creates a user in the Auth emulator.
 * @param email Optional email; a unique one is generated by default.
 * @returns The new user's uid and a Firebase ID token.
 */
export async function signUp(
  email = `user-${Date.now()}-${counter++}@example.com`,
): Promise<{ uid: string; idToken: string }> {
  const res = await fetch(SIGN_UP_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      email,
      password: 'test-password-123',
      returnSecureToken: true,
    }),
  });
  if (!res.ok)
    throw new Error(`signUp failed: ${res.status} ${await res.text()}`);
  const json = (await res.json()) as { localId: string; idToken: string };
  return { uid: json.localId, idToken: json.idToken };
}

/**
 * Creates the stock Genkit remote agent client for the test function.
 * @param idToken Firebase ID token sent as a bearer token.
 */
export function client(idToken: string) {
  return remoteAgent({
    url: FUNCTION_URL,
    headers: { Authorization: `Bearer ${idToken}` },
  });
}

/** JSON body of a raw response: a `result` on success, or an error. */
export interface RawBody {
  result?: unknown;
  status?: string;
  message?: string;
}

/**
 * Sends a raw POST to the function for status code assertions.
 * @param path Route under the function URL, for example `/` or `/getSnapshot`.
 * @param body JSON body.
 * @param idToken Optional bearer token.
 */
export async function postRaw(
  path: string,
  body: unknown,
  idToken?: string,
): Promise<{ status: number; body: RawBody }> {
  const res = await fetch(`${FUNCTION_URL}${path === '/' ? '' : path}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(idToken ? { Authorization: `Bearer ${idToken}` } : {}),
    },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  let parsed: RawBody = {};
  try {
    parsed = JSON.parse(text);
  } catch {
    parsed = { message: text };
  }
  return { status: res.status, body: parsed };
}

/**
 * Fails the test when `value` is null or undefined, and narrows its type.
 * @param value Value to check.
 * @param what Name used in the failure message.
 */
export function defined<T>(value: T | null | undefined, what: string): T {
  if (value === null || value === undefined) {
    throw new Error(`Expected ${what} to be defined`);
  }
  return value;
}
